using DadoRetail.Api.Security;using DadoRetail.Application.Security;using DadoRetail.Domain.Inventory;using DadoRetail.Domain.Purchasing;using DadoRetail.Infrastructure.Persistence;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace DadoRetail.Api.Controllers;
[ApiController,Route("api/v1/purchases")]public sealed class PurchasesController(DadoRetailDbContext db):ControllerBase{
[HttpGet,HasPermission(Permissions.ProductView)]public async Task<IActionResult>List(CancellationToken ct)=>Ok(await db.Purchases.AsNoTracking().Include(x=>x.Items).OrderByDescending(x=>x.CreatedAtUtc).Take(500).Select(x=>new{x.Id,x.SupplierId,x.WarehouseId,x.DocumentNumber,x.Status,x.PostedAtUtc,Items=x.Items.Count,Total=x.Items.Sum(i=>i.Quantity*i.PurchasePrice)}).ToListAsync(ct));
[HttpPost,HasPermission(Permissions.PurchaseCreate)]public async Task<IActionResult>Create(CreatePurchaseRequest r,CancellationToken ct){var p=new Purchase(r.SupplierId,r.WarehouseId,r.DocumentNumber);db.Purchases.Add(p);await db.SaveChangesAsync(ct);return Ok(new{p.Id,p.Status});}
[HttpPost("{id:guid}/items/by-barcode"),HasPermission(Permissions.PurchaseCreate)]public async Task<IActionResult>AddItem(Guid id,AddPurchaseItemRequest r,CancellationToken ct){var p=await db.Purchases.Include(x=>x.Items).FirstOrDefaultAsync(x=>x.Id==id,ct);if(p is null)return NotFound();if(p.Status!=DocumentStatus.Draft)return Conflict(new{message="Проведенный или отмененный документ нельзя редактировать"});var productId=await db.Barcodes.Where(x=>x.Value==r.Barcode).Select(x=>(Guid?)x.ProductId).FirstOrDefaultAsync(ct);if(productId is null)return NotFound(new{message="Товар по штрихкоду не найден"});var item=p.AddItem(productId.Value,r.Quantity,r.PurchasePrice,r.ExpiryDate);db.Entry(item).State=EntityState.Added;await db.SaveChangesAsync(ct);return Ok(new{p.Id,items=p.Items.Count});}
[HttpPost("{id:guid}/post"),HasPermission(Permissions.PurchasePost)]public async Task<IActionResult>Post(Guid id,CancellationToken ct){await using var tx=await db.Database.BeginTransactionAsync(ct);var p=await db.Purchases.Include(x=>x.Items).FirstOrDefaultAsync(x=>x.Id==id,ct);if(p is null)return NotFound();if(p.Status!=DocumentStatus.Draft)return Conflict(new{message="Документ уже проведен или отменен"});foreach(var i in p.Items){var b=await db.StockBalances.FirstOrDefaultAsync(x=>x.WarehouseId==p.WarehouseId&&x.ProductId==i.ProductId,ct);if(b is null){b=new StockBalance(p.WarehouseId,i.ProductId);db.StockBalances.Add(b);}b.Apply(i.Quantity);db.StockMovements.Add(new StockMovement(p.WarehouseId,i.ProductId,i.Quantity,StockMovementType.Receipt,p.Id));}p.MarkPosted();await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return Ok(new{p.Id,p.Status,p.PostedAtUtc});}}
public sealed record CreatePurchaseRequest(Guid SupplierId,Guid WarehouseId,string DocumentNumber);public sealed record AddPurchaseItemRequest(string Barcode,decimal Quantity,decimal PurchasePrice,DateOnly? ExpiryDate);
